// La RPC devuelve un array JSON en el body. Lo dividimos en items y
// construimos el mensaje por estado (réplica de mensajeWhatsAppEstado).
const base = ($vars.TRACKING_BASE_URL || '').replace(/\/+$/, '');
const pend = $input.first().json;
const lista = Array.isArray(pend) ? pend : (Array.isArray(pend.data) ? pend.data : []);

const plantilla = (p) => {
  const nombre = p.nombre ? `, ${p.nombre}` : '';
  const url = `${base}?codigo=${p.codigo}`;
  const saldo = Math.max(0, Number(p.saldo || 0)).toFixed(2);
  const seg = `Consulta tu seguimiento aquí: ${url}`;
  const m = {
    pedido_confirmado: `Hola${nombre}. Confirmamos tu orden ${p.codigo}. Ya quedó registrada y te avisaremos cada avance. ${seg}`,
    en_preparacion: `Hola${nombre}. Tu pedido ${p.codigo} está en preparación. ${seg}`,
    control_calidad: `Hola${nombre}. Tu pedido ${p.codigo} está en control de calidad. ${seg}`,
    etiqueta_creada: `Hola${nombre}. Ya fue creada la etiqueta de envío de tu pedido ${p.codigo}. ${seg}`,
    despachado: `📦 Hola${nombre}. Tu pedido ${p.codigo} ya fue despachado y está en tránsito. ${seg}`,
    transito_internacional: `📦 Hola${nombre}. Tu pedido ${p.codigo} está en tránsito internacional. ${seg}`,
    recibido_estados_unidos: `Hola${nombre}. Tu pedido ${p.codigo} fue recibido en Estados Unidos y sigue hacia Nicaragua. ${seg}`,
    transito_nicaragua: `📦 Hola${nombre}. Tu pedido ${p.codigo} ya viaja hacia Nicaragua. ${seg}`,
    llego_nicaragua: `Hola${nombre}. Tu pedido ${p.codigo} ya llegó a Nicaragua y está siendo procesado. ${seg}`,
    disponible_entrega: `✅ Hola${nombre}. Tu pedido HAUSLINE ${p.codigo} ya está disponible. Saldo pendiente: USD ${saldo}. ${seg}\nEscríbenos para coordinar la entrega o retiro.`,
    entregado: `Hola${nombre}. Tu pedido ${p.codigo} fue entregado. ¡Gracias por comprar en HAUSLINE!`,
  };
  return m[p.estado] || `Hola${nombre}. 📦 Actualización de tu pedido HAUSLINE ${p.codigo}: ${p.estado_label}. ${seg}`;
};

return lista.map((p) => ({ json: { ...p, mensaje: plantilla(p) } }));
